from collections import Counter


def transform(grid):
    """Retain near-solid rectangular objects; erase off-object speckles."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != background}
    candidates = []

    for color in colors:
        # 2-D prefix sum makes exhaustive rectangle scoring inexpensive.
        pref = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            run = 0
            for c in range(w):
                run += grid[r][c] == color
                pref[r + 1][c + 1] = pref[r][c + 1] + run

        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                rh = r1 - r0 + 1
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        cw = c1 - c0 + 1
                        area = rh * cw
                        count = (pref[r1 + 1][c1 + 1] - pref[r0][c1 + 1]
                                 - pref[r1 + 1][c0] + pref[r0][c0])
                        if count < max(3, area * 0.70):
                            continue
                        # Exclude wide bounding boxes that bridge disjoint blobs.
                        row_ok = all(
                            pref[r + 1][c1 + 1] - pref[r][c1 + 1]
                            - pref[r + 1][c0] + pref[r][c0] >= cw * 0.5
                            for r in range(r0, r1 + 1))
                        col_ok = all(
                            pref[r1 + 1][c + 1] - pref[r0][c + 1]
                            - pref[r1 + 1][c] + pref[r0][c] >= rh * 0.5
                            for c in range(c0, c1 + 1))
                        if row_ok and col_ok:
                            candidates.append((area, count / area, color, r0, r1, c0, c1))

    candidates.sort(reverse=True)
    selected = []
    occupied = [[False] * w for _ in range(h)]
    for area, density, color, r0, r1, c0, c1 in candidates:
        if any(occupied[r][c] for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)):
            continue
        selected.append((color, r0, r1, c0, c1))
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                occupied[r][c] = True

    out = [[background] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in selected:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out


